{
  "name": "opencode-beads_rust-stats-sidebar",
  "version": "1.1.1",
  "description": "OpenCode V2 plugin that displays beads_rust (br) issue statistics, a focused epic with its tasks, and ready-to-close epics in the TUI sidebar.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "beads",
    "beads-rust",
    "tui",
    "solidjs",
    "typescript"
  ],
  "homepage": "https://github.com/melik/opencode-beads_rust-stats-sidebar#readme",
  "bugs": {
    "url": "https://github.com/melik/opencode-beads_rust-stats-sidebar/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/melik/opencode-beads_rust-stats-sidebar.git"
  },
  "license": "MIT",
  "author": "Alexey M (https://github.com/melik)",
  "type": "module",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx",
    "./rpc": "./rpc.ts"
  },
  "main": "index.js",
  "files": [
    "index.ts",
    "tui.tsx",
    "rpc.ts",
    "beads.ts",
    "display.ts",
    "i18n.ts",
    "tsconfig.json",
    "README.md"
  ],
  "scripts": {
    "test": "node --test beads.test.ts display.test.ts i18n.test.ts package.test.ts",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm test && npm run typecheck"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "devDependencies": {
    "typescript": "^5.6.0",
    "@types/node": "^22.0.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.6.6",
    "@opentui/solid": ">=0.6.6",
    "solid-js": ">=1.9.0"
  },
  "engines": {
    "node": ">=22.6.0"
  }
}
